import{_ as o,o as r,c as t,a5 as s}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"beforeEach vs beforeResolve","description":"Vue Router 守卫体系： beforeEach vs beforeResolve 一、整体思路 在 Vue Router 中，导航守卫的触发顺序大致是： 1. 全局前置守卫 → router.beforeEach 2. 路由配置里单个路由的守卫 → beforeEnter。","frontmatter":{"title":"beforeEach vs beforeResolve","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"Vue Router 守卫体系： beforeEach vs beforeResolve 一、整体思路 在 Vue Router 中，导航守卫的触发顺序大致是： 1. 全局前置守卫 → router.beforeEach 2. 路由配置里单个路由的守卫 → beforeEnter。","sidebarWeight":37,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/导航守卫/`beforeEach` vs `beforeResolve`.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/导航守卫/beforeEach vs beforeResolve.md","filePath":"posts/Vue系统教程/04-路由与状态管理/导航守卫/beforeEach vs beforeResolve.md"}'),l={name:"posts/Vue系统教程/04-路由与状态管理/导航守卫/beforeEach vs beforeResolve.md"};function n(a,e,g,i,c,f){return r(),t("div",null,[...e[0]||(e[0]=[s('<div><h1 id="beforeeach-vs-beforeresolve" tabindex="-1">beforeEach vs beforeResolve <a class="header-anchor" href="#beforeeach-vs-beforeresolve" aria-label="Permalink to &quot;beforeEach vs beforeResolve&quot;">​</a></h1><blockquote><p>本节目标：理解“beforeEach vs beforeResolve”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><h1 id="vue-router-守卫体系-beforeeach-vs-beforeresolve" tabindex="-1">Vue Router 守卫体系：****<code>beforeEach</code>** <strong>vs</strong> **<code>beforeResolve</code> <a class="header-anchor" href="#vue-router-守卫体系-beforeeach-vs-beforeresolve" aria-label="Permalink to &quot;Vue Router 守卫体系：****`beforeEach`** **vs** **`beforeResolve`&quot;">​</a></h1><h2 id="一、整体思路" tabindex="-1">一、整体思路 <a class="header-anchor" href="#一、整体思路" aria-label="Permalink to &quot;一、整体思路&quot;">​</a></h2><p>在 Vue Router 中，导航守卫的触发顺序大致是：</p><ol><li><strong><strong>全局前置守卫</strong></strong> → <code>router.beforeEach</code></li><li><strong><strong>路由配置里单个路由的守卫</strong></strong> → <code>beforeEnter</code></li><li><strong><strong>组件内的守卫</strong></strong> → <code>beforeRouteEnter</code></li><li><strong><strong>全局解析守卫</strong></strong> → <code>router.beforeResolve</code></li><li><strong><strong>全局后置守卫</strong></strong> → <code>router.afterEach</code> 👉 其中 <code>beforeEach</code> 和 <code>beforeResolve</code> 看似相似，实际上适合放<strong><strong>不同阶段的逻辑</strong></strong>。</li></ol><h2 id="二、-beforeeach-的作用" tabindex="-1">二、****<code>beforeEach</code>** **的作用 <a class="header-anchor" href="#二、-beforeeach-的作用" aria-label="Permalink to &quot;二、****`beforeEach`** **的作用&quot;">​</a></h2><ul><li><strong><strong>时机</strong></strong>：在任何导航被触发时，最先执行。</li><li><strong><strong>特点</strong></strong>：可取消，可重定向。</li><li><strong><strong>常用用途</strong></strong>： <ol><li><strong><strong>身份认证检查</strong></strong> router.beforeEach((to, _from, next) =&gt; { if (to.meta.requiresAuth &amp;&amp; !userStore.isLoggedIn) { return next({ name: &#39;login&#39;, query: { redirect: to.fullPath } }) } next() }) 说明：适合做“是否允许进入”的逻辑。</li><li><strong><strong>基础拦截（黑名单/白名单）</strong></strong><ul><li>公共页面白名单 (<code>/login</code>, <code>/register</code>)</li><li>需要角色权限的页面（如后台管理）</li></ul></li><li><strong><strong>页面级别 loading / NProgress</strong></strong><ul><li>在导航一开始时启动页面进度条。</li></ul></li></ol></li></ul><h2 id="三、-beforeresolve-的作用" tabindex="-1">三、****<code>beforeResolve</code>** **的作用 <a class="header-anchor" href="#三、-beforeresolve-的作用" aria-label="Permalink to &quot;三、****`beforeResolve`** **的作用&quot;">​</a></h2><ul><li><strong><strong>时机</strong></strong>：在所有异步路由组件被解析完成、且 <code>beforeEnter</code>/组件内 <code>beforeRouteEnter</code> 都通过后，才会触发。</li><li><strong><strong>特点</strong></strong>：也可取消，可重定向，但它离导航“确认”最近。</li><li><strong><strong>常用用途</strong></strong>： <ol><li><strong><strong>数据预取（Data Prefetch）</strong></strong> router.beforeResolve(async (to, _from, next) =&gt; { try { if (to.meta.prefetch) { await api.fetchPageData(to.name as string) } next() } catch (err) { console.error(err) next(false) // 阻止导航 } }) 说明：确保进入页面前数据准备好。</li><li><strong><strong>权限二次确认</strong></strong><ul><li>在组件内动态加载权限数据后，再决定是否放行。</li><li>避免因为异步校验导致用户先闪现页面。</li></ul></li><li><strong><strong>SSR/SEO 场景</strong></strong><ul><li>确保进入路由前数据都加载完成，利于首屏完整渲染。</li></ul></li></ol></li></ul><h2 id="四、最佳实践推荐" tabindex="-1">四、最佳实践推荐 <a class="header-anchor" href="#四、最佳实践推荐" aria-label="Permalink to &quot;四、最佳实践推荐&quot;">​</a></h2><p>在大厂或中大型项目里，通常会这样分工：</p><ul><li><strong><strong><strong><strong><code>beforeEach</code></strong></strong></strong></strong><ul><li>全局身份校验（登录态、token 有效性）</li><li>简单的白名单拦截（不需要请求接口即可判断的）</li></ul></li><li><strong><strong><strong><strong><code>beforeResolve</code></strong></strong></strong></strong><ul><li>依赖接口/异步逻辑的权限判断（比如是否已绑定手机号、是否有二次验证）</li><li>页面必要数据预取（接口请求 + loading）</li><li>在 SSR/SEO 场景下，保证路由切换前就拿到数据</li></ul></li><li><strong><strong><strong><strong><code>afterEach</code></strong></strong></strong></strong><ul><li>日志埋点（PV/UV 上报）</li><li>停止进度条</li><li>页面标题设置</li></ul></li></ul><h2 id="五、总结" tabindex="-1">五、总结 <a class="header-anchor" href="#五、总结" aria-label="Permalink to &quot;五、总结&quot;">​</a></h2><ul><li><code>beforeEach</code> = <strong><strong>粗过滤、身份校验、快速拦截</strong></strong></li><li><code>beforeResolve</code> = <strong><strong>细过滤、异步数据准备、SSR 数据依赖</strong></strong></li><li>最佳实践： <ul><li>**<strong>能同步判断的放</strong> <strong><code>beforeEach</code></strong>******（快速决策）</li><li>**<strong>要异步/依赖数据的放</strong> <strong><code>beforeResolve</code></strong>******（在确认前最后拦截）</li></ul></li></ul><p>要不要我帮你写一个 <strong><strong>大厂级别的守卫注册文件模板</strong></strong>（带 <code>beforeEach</code>、<code>beforeResolve</code>、<code>afterEach</code> 三类逻辑分层）？这样你能直接落地用在你项目里。 13. <strong>什么时候会白屏？</strong> - 如果你在 beforeEach 里做了 await fetch()，这时路由还没解析，Vue 还没去加载目标组件，&lt;router-view&gt; 里什么都没有——就会白屏。 14. <strong>为什么 beforeResolve 不白屏？</strong> - 路由在进入 beforeResolve 之前，已经把目标组件（包括所有异步组件）都「解析（import）」好了，这时虽然还没真正 mount，但 &lt;router-view&gt; 可以先渲染一个 Suspense fallback 或者是前一个路由的内容，不会直接出现纯白。 <strong>具体做法</strong><strong>1. 在 App.vue 用 &lt;Suspense&gt; 包裹 &lt;router-view&gt;</strong> 只需要调整这几行，不要贴整个文件。 &lt;template&gt;- &lt;router-view /&gt;+ &lt;Suspense&gt;+ &lt;template #default&gt;&lt;router-view/&gt;&lt;/template&gt;+ &lt;!-- 异步组件加载前的骨架/Spinner --&gt;+ &lt;template #fallback&gt;&lt;LoadingSpinner/&gt;&lt;/template&gt;+ &lt;/Suspense&gt;&lt;/template&gt; 这样，不管你是 beforeEach 还是 beforeResolve 里拦截，只要组件还没挂载，用户都能看到 &lt;Suspense&gt; 的 fallback，就不会白屏。</p></div>',1)])])}const b=o(l,[["render",n]]);export{d as __pageData,b as default};
